 const a=JSON.parse(load("issues/"+n).output),pages=JSON.parse(load("issues/"+n+"/comments").output),comments=pages.flat(),b=JSON.parse(load("refresh/"+n).output);
 if (a.updated_at!==b.updated_at||a.comments!==b.comments||new Set(comments.map(x=>x.id)).size!==a.comments) throw Error("snapshot mismatch");
 out+=`## Issue #${n}: ${a.title}

- URL: ${a.html_url}
- State: ${a.state}
- Author: ${a.user.login}
- Created: ${a.created_at}
- Updated: ${a.updated_at}
- Milestone: ${a.milestone?.title??"unset; body assigns M1"}
- Labels: ${a.labels.map(x=>x.name).join(", ")}
- Assignees: ${a.assignees.map(x=>x.login).join(", ")||"none"}
- Comments: ${comments.length}; completeness/stability checks passed.

### Complete body

${a.body}

`;
 for(const c of comments.sort((x,y)=>x.created_at.localeCompare(y.created_at)||x.id-y.id))out+=`### Comment ${c.id} — ${c.user.login}

Created ${c.created_at}; updated ${c.updated_at}.
[Direct comment](${c.html_url})

${c.body}

`;
}
